func equalAuthorityInventory(a, b playerInventorySaveState) bool {
	if a.SkullKeys != b.SkullKeys {
		return false
	}
	if a.BlueKey != b.BlueKey {
		return false
	}
	if a.RedKey != b.RedKey {
		return false
	}
	if a.YellowKey != b.YellowKey {
		return false
	}
	if a.Backpack != b.Backpack {
		return false
	}
	if a.Strength != b.Strength {
		return false
	}
	if a.StrengthCount != b.StrengthCount {
		return false
	}
	if a.InvulnTics != b.InvulnTics {
		return false
	}
	if a.InvisTics != b.InvisTics {
		return false
	}
	if a.RadSuitTics != b.RadSuitTics {
		return false
	}
	if a.AllMap != b.AllMap {
		return false
	}
	if a.LightAmpTics != b.LightAmpTics {
		return false
	}
	if a.ReadyWeapon != b.ReadyWeapon {
		return false
	}
	if a.PendingWeapon != b.PendingWeapon {
		return false
	}
	if (a.Weapons == nil) != (b.Weapons == nil) || !maps.Equal(a.Weapons, b.Weapons) {
		return false
	}
	return true
}
